namespace ContosoUniversity.Tests
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateAndRetrieveStudent()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            context.Students.Add(new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            });
            context.SaveChanges();

            var student = context.Students.First();
            Assert.Equal("Test", student.FirstMidName);
            Assert.Equal("Student", student.LastName);
            Assert.Equal(new DateTime(2023, 1, 1), student.EnrollmentDate);
        }

        [Fact]
        public void SchoolContext_CanCreateAndRetrieveCourse()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var dept = new Department { Name = "Test", Budget = 100, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            context.Courses.Add(new Course
            {
                CourseID = 999,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            });
            context.SaveChanges();

            var course = context.Courses.First(c => c.CourseID == 999);
            Assert.Equal("Test Course", course.Title);
            Assert.Equal(3, course.Credits);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            using var context = TestHelpers.CreateInMemoryContext();
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
            context.Instructors.Add(instructor);
            var dept = new Department { Name = "Dept", Budget = 100, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments.First();
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void SchoolContext_CanCreateEnrollment()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);
            var dept = new Department { Name = "Dept", Budget = 100, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 200, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = Grade.A };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var retrieved = context.Enrollments.First();
            Assert.Equal(student.ID, retrieved.StudentID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(Grade.A, retrieved.Grade);
        }

        [Fact]
        public void SchoolContext_HasAllDbSets()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.People);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_OfficeAssignment_OneToOneWithInstructor()
        {
            using var context = TestHelpers.CreateInMemoryContext();

            var instructor = new Instructor { FirstMidName = "Test", LastName = "Prof", HireDate = DateTime.Now };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 101" };
            context.OfficeAssignments.Add(office);
            context.SaveChanges();

            var retrieved = context.OfficeAssignments.First();
            Assert.Equal(instructor.ID, retrieved.InstructorID);
            Assert.Equal("Room 101", retrieved.Location);
        }
    }
}

