+        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
+        {
+            _service.SendNotification("Student", "99", EntityOperation.CREATE);
+
+            var notification = _service.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutUserName_DefaultsToSystem()
+        {
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+
+            var notification = _service.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void SendNotification_SetsCreatedAtToApproximatelyNow()
+        {
+            var before = DateTime.Now.AddSeconds(-1);
+            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
+            var after = DateTime.Now.AddSeconds(1);
+
+            var notification = _service.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.InRange(notification.CreatedAt, before, after);
+        }
+
+        [Fact]
+        public void ReceiveNotification_EmptyQueue_ReturnsNull()
+        {
+            var result = _service.ReceiveNotification();
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
+        {
+            _service.SendNotification("A", "1", EntityOperation.CREATE);
+            _service.SendNotification("B", "2", EntityOperation.UPDATE);
+            _service.SendNotification("C", "3", EntityOperation.DELETE);
+
+            var first = _service.ReceiveNotification();
+            var second = _service.ReceiveNotification();
+            var third = _service.ReceiveNotification();
+
+            Assert.Equal("A", first!.EntityType);
+            Assert.Equal("B", second!.EntityType);
+            Assert.Equal("C", third!.EntityType);
+        }
+
+        [Fact]
+        public void MarkAsRead_DoesNotThrow()
+        {
+            // MarkAsRead is a no-op for in-memory implementation
+            var exception = Record.Exception(() => _service.MarkAsRead(1));
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_NullDisplayName_UsesIdFallback()
+        {
+            _service.SendNotification("Student", "5", null, EntityOperation.UPDATE);
+
+            var notification = _service.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("Student (ID: 5) has been updated", notification.Message);
+        }
+
+        [Fact]
+        public void SendNotification_EmptyDisplayName_UsesIdFallback()
+        {
+            _service.SendNotification("Student", "5", "  ", EntityOperation.DELETE);
+
+            var notification = _service.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("Student (ID: 5) has been deleted", notification.Message);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            var service = new NotificationService();
+            var exception = Record.Exception(() => service.Dispose());
+            Assert.Null(exception);
+        }
+    }
+}
