        // --- File extension validation ---

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_Post_AllowedExtensions_DoNotFail(string extension)
        {
            var course = new Course { CourseID = 7000 + extension.GetHashCode(), Title = "Test", Credits = 3, DepartmentID = 1 };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");
            mockFile.Setup(f => f.Length).Returns(100);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object);

            // Should redirect (success) or return view without teachingMaterialImage error
            if (result is ViewResult viewResult)
            {
                // If it returned a view, it shouldn't be because of file extension
                Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage") &&
                    _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("valid image")));
            }
        }
