using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using System;
using Xunit;

namespace ContosoUniversity.Tests
{
    // Test a concrete subclass of BaseController to verify base behavior
    public class TestableController : BaseController
    {
        public TestableController(SchoolContext context) : base(context) { }

        // Expose protected methods for testing
        public void TestSendEntityNotification(string entityType, string entityId, EntityOperation operation)
        {
            SendEntityNotification(entityType, entityId, operation);
        }

        public void TestSendEntityNotificationWithName(string entityType, string entityId, string entityDisplayName, EntityOperation operation)
        {
            SendEntityNotification(entityType, entityId, entityDisplayName, operation);
        }

        public void TestDispose()
        {
            Dispose(true);
        }
    }

    public class BaseControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly TestableController _controller;

        public BaseControllerTests()
        {
            _context = TestHelpers.CreateInMemoryContext();
            _controller = new TestableController(_context);
            // Drain static queue
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            svc.Dispose();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void SendEntityNotification_WithoutDisplayName_EnqueuesNotification()
        {
            _controller.TestSendEntityNotification("Student", "1", EntityOperation.CREATE);

            var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            svc.Dispose();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
        }

        [Fact]
        public void SendEntityNotification_WithDisplayName_EnqueuesNotification()
        {
            _controller.TestSendEntityNotificationWithName("Course", "42", "Chemistry", EntityOperation.UPDATE);

            var svc = new NotificationService();
            var notification = svc.ReceiveNotification();
            svc.Dispose();

            Assert.NotNull(notification);
            Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
            Assert.Equal("System", notification.CreatedBy); // Default userName
        }

        [Fact]
        public void SendEntityNotification_DoesNotThrowOnError()
        {
            // Even if notification fails, it shouldn't throw
            var exception = Record.Exception(() =>
                _controller.TestSendEntityNotification("Test", "1", EntityOperation.DELETE));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DisposesContextAndService()
        {
            var context = TestHelpers.CreateInMemoryContext();
            var controller = new TestableController(context);

            var exception = Record.Exception(() => controller.TestDispose());
            Assert.Null(exception);
        }
    }
}

