        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverMaxQueueLength_EvictsOldMessages()
        {
            // The queue has a max of 500 items; send 510 to verify eviction
            for (int i = 0; i < 510; i++)
            {
                _service.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Drain queue and count
            int count = 0;
            while (_service.ReceiveNotification() != null) count++;

            // Should have evicted oldest entries - count must be <= 500
            Assert.True(count <= 500, $"Expected <=500 but got {count}");
        }

        [Fact]
